arguments.argument:
var old, ind;

global.cur_bkg_image += 1;

if( ds_list_size( bkg_image_list ) <= global.cur_bkg_image ){
    global.cur_bkg_image = 0;
}

ind = background_add(ds_list_find_value( bkg_image_list, global.cur_bkg_image), false, false);

old = background_index[1];
background_index[1] = ind;

if(  background_exists( old ) && old != ind ){
    background_delete( old );
}
